update public.chapters as chapters
set title = case when eligible.language = 'kk' then labels.kk else labels.ru end
from question_bank_v3_standard_books as eligible
join labels on labels.slug = eligible.slug
join old_labels on old_labels.position = labels.position
where chapters.book_id = eligible.book_id
  and chapters.position = labels.position
  and chapters.deleted_at is null
  and chapters.title in (old_labels.ru, old_labels.kk, old_labels.en);

update public.questions as questions
set chapter_id = chapters.id,
  position = (catalog.number - 1) % eligible.questions_per_chapter + 1
from public.question_catalog as catalog
join public.book_types as types on types.id = catalog.book_type_id
join question_bank_v3_standard_books as eligible on eligible.slug = types.slug
join public.chapters as chapters
  on chapters.book_id = eligible.book_id
 and chapters.position = (catalog.number - 1) / eligible.questions_per_chapter + 1
 and chapters.deleted_at is null
where questions.book_id = eligible.book_id
  and questions.catalog_id = catalog.id
  and questions.deleted_at is null;

drop table question_bank_v3_standard_books;

create or replace function public.instantiate_book_template(target_book_id uuid)
returns void language plpgsql security definer set search_path = '' as $$
declare
  book_type uuid;
  book_type_slug text;
  selected_language public.book_language;
  expected_question_count integer;
  questions_per_chapter integer;
  expected_chapter_count integer;
  ru_titles text[];
  kk_titles text[];
  chapter_titles text[];
begin
  select books.type_id, types.slug, books.language
  into book_type, book_type_slug, selected_language
  from public.books as books
  join public.book_types as types on types.id = books.type_id
  where books.id = target_book_id and books.deleted_at is null
  for update of books;

  if not found or exists(select 1 from public.chapters where book_id = target_book_id) then return; end if;

  expected_question_count := case when book_type_slug in ('girlfriend', 'boyfriend', 'wife', 'husband', 'mother', 'father', 'parents', 'sister', 'brother', 'friend', 'female-friend') then 150 else 100 end;
  questions_per_chapter := case when book_type_slug in ('girlfriend', 'boyfriend') then 30 else 25 end;
  expected_chapter_count := expected_question_count / questions_per_chapter;
  if (select count(*) from public.question_catalog where book_type_id = book_type) <> expected_question_count then
    raise exception 'Recipient catalog must contain % questions', expected_question_count;
  end if;

  case book_type_slug
  when 'girlfriend' then
    ru_titles := array['С чего всё началось', 'Я люблю тебя такой', 'Наш маленький мир', 'Незабываемые моменты', 'Впереди ещё столько глав'];
    kk_titles := array['Бәрі неден басталды', 'Мен сені осындайың үшін жақсы көремін', 'Біздің кішкентай әлеміміз', 'Ұмытылмайтын сәттер', 'Әлі талай тарау алда'];
  when 'boyfriend' then
    ru_titles := array['С чего всё началось', 'Я люблю тебя таким', 'То, что понятно только нам', 'Дни, которые мы не забудем', 'С тобой — вперёд'];
    kk_titles := array['Бәрі неден басталды', 'Мен сені осындайың үшін жақсы көремін', 'Тек екеуімізге түсінікті', 'Біз ұмытпайтын күндер', 'Сенімен бірге — алға'];
  when 'wife' then
    ru_titles := array['С чего всё началось', 'Когда «я» и «ты» стали «мы»', 'День, когда мы стали семьёй', 'Наш маленький семейный мир', 'Всё, что мы пережили вместе', 'Через всё — вместе'];
    kk_titles := array['Бәрі неден басталды', '«Мен» мен «сен» — «бізге» айналғанда', 'Отбасы болған күніміз', 'Біздің кішкентай отбасылық әлеміміз', 'Бірге бастан өткерген сәттер', 'Қандай жағдай болса да — бірге'];
  when 'husband' then
    ru_titles := array['С чего всё началось', 'Когда он стал тем самым', 'День, когда мы стали семьёй', 'Наш маленький семейный мир', 'Муж, которого вижу я', 'Через всё — вместе'];
    kk_titles := array['Бәрі неден басталды', 'Оның «дәл сол адам» екенін түсінгенде', 'Отбасы болған күніміз', 'Біздің кішкентай отбасылық әлеміміз', 'Менің көзімдегі сен', 'Қандай жағдай болса да — бірге'];
  when 'mother' then
    ru_titles := array['Там, где всё начиналось', 'Детство глазами взрослого', 'Мама, которую знаю только я', 'Не только мама', 'Мы выросли вместе', 'Всё, что я хочу тебе сказать'];
    kk_titles := array['Бәрі басталған кез', 'Балалық шаққа ересек адамның көзімен', 'Мен білетін ана', 'Тек ана ғана емес', 'Біз бірге есейдік', 'Сізге айтқым келетін сөздер'];
  when 'father' then
    ru_titles := array['Там, где всё начиналось', 'Всё, чему он меня научил', 'Папа, которого знаю только я', 'До того, как он стал папой', 'Мы менялись вместе', 'То, что я хочу успеть тебе сказать'];
    kk_titles := array['Бәрі басталған кез', 'Әкем үйреткен өмір сабақтары', 'Мен білетін әке', 'Әке атанғанға дейін', 'Біз бірге өзгердік', 'Сізге айтқым келетін сөздер'];
  when 'parents' then
    ru_titles := array['Дом, в котором всё начиналось', 'Всё, чему меня научила наша семья', 'Мама и папа, которых знаю я', 'До того, как появилась наша семья', 'Всё, что мы прошли вместе', 'То, что хочется успеть сказать'];
    kk_titles := array['Бәрі басталған үй', 'Отбасымнан үйренгенім', 'Мен білетін анам мен әкем', 'Біздің отбасы құрылғанға дейін', 'Біз бірге өткерген жол', 'Айтылып қалуы керек сөздер'];
  when 'sister' then
    ru_titles := array['Мы росли вместе', 'Ссоры, секреты и союз против всего мира', 'Сестра, которую знаю только я', 'От сестёр к близким друзьям', 'Только наши воспоминания', 'Сколько бы лет ни прошло'];
    kk_titles := array['Біз бірге өстік', 'Ұрыстар, құпиялар және екеуіңіз бір команда болған кездер', 'Мен ғана жақсы білетін жан', 'Туысқаннан жақын досқа дейін', 'Тек екеуіңізге тиесілі естеліктер', 'Қанша жыл өтсе де'];
  when 'brother' then
    ru_titles := array['Мы росли вместе', 'Шалости, соревнования и один секрет на двоих', 'Брат, которого знаю я', 'От детских ссор к настоящему доверию', 'Только наши воспоминания', 'Сколько бы лет ни прошло'];
    kk_titles := array['Біз бірге өстік', 'Тентектік, жарыс және екеуіңізге ортақ бір құпия', 'Мен білетін бауырым', 'Балалық ұрыстардан шынайы сенімге дейін', 'Тек екеуіңізге тиесілі естеліктер', 'Қанша жыл өтсе де'];
  when 'friend' then
    ru_titles := array['С чего всё началось', 'Истории, которые лучше не забывать', 'Только мы это понимаем', 'Друг, которого знаю я', 'Когда дружба становится чем-то большим', 'Ещё много историй впереди'];
    kk_titles := array['Бәрі неден басталды', 'Ұмытылмайтын оқиғалар', 'Мұны тек біз түсінеміз', 'Мен білетін досым', 'Достық жай ғана достықтан да маңызды болғанда', 'Алда әлі талай оқиға бар'];
  when 'female-friend' then
    ru_titles := array['С чего всё началось', 'Те самые истории', 'Это поймём только мы', 'Подруга, которую знаю я', 'Когда подруга становится родным человеком', 'Ещё столько всего впереди'];
    kk_titles := array['Бәрі неден басталды', 'Ұмытылмайтын оқиғалар', 'Мұны тек екеуіміз түсінеміз', 'Мен білетін құрбым', 'Құрбың туған адамыңдай жақын болғанда', 'Алда әлі талай қызық бар'];
  else
    ru_titles := array['С чего всё началось', 'Самое дорогое', 'Наши воспоминания', 'О главном и о будущем'];
    kk_titles := array['Бәрі неден басталды', 'Ең қымбат нәрселер', 'Біздің естеліктеріміз', 'Ең маңыздысы және болашақ туралы'];
  end case;
  chapter_titles := case when selected_language = 'kk' then kk_titles else ru_titles end;

  insert into public.chapters(book_id, title, position)
  select target_book_id, chapter_titles[position], position
  from generate_series(1, expected_chapter_count) as position;

  insert into public.questions(book_id, chapter_id, catalog_id, prompt, position)
  select target_book_id, chapters.id, catalog.id, coalesce(translations.prompt, catalog.prompt),
    (catalog.number - 1) % questions_per_chapter + 1
  from public.question_catalog as catalog
  join public.chapters as chapters
    on chapters.book_id = target_book_id
   and chapters.position = (catalog.number - 1) / questions_per_chapter + 1
  left join public.question_catalog_translations as translations
    on translations.catalog_id = catalog.id and translations.language = selected_language
  where catalog.book_type_id = book_type;
end;
$$;

create or replace function public.set_book_language(target_book_id uuid, target_language public.book_language)
returns boolean language plpgsql security definer set search_path = '' as $$
declare
  book_type_slug text;
  ru_titles text[];
  kk_titles text[];
  chapter_titles text[];
  system_titles text[];
begin
  select types.slug into book_type_slug
  from public.books as books
  join public.book_types as types on types.id = books.type_id
  where books.id = target_book_id and books.deleted_at is null
  for update of books;
  if not found then return false; end if;

  perform set_config('app.changing_book_language', 'true', true);
  update public.books set language = target_language where id = target_book_id;
  update public.questions as questions
  set prompt = coalesce(
    (select overrides.prompt from public.question_prompt_overrides as overrides
      where overrides.question_id = questions.id and overrides.language = target_language),
    (select translations.prompt from public.question_catalog_translations as translations
      where translations.catalog_id = questions.catalog_id and translations.language = target_language),
    (select catalog.prompt from public.question_catalog as catalog where catalog.id = questions.catalog_id)
  )
  where questions.book_id = target_book_id and questions.catalog_id is not null and questions.deleted_at is null;

  case book_type_slug
  when 'girlfriend' then
    ru_titles := array['С чего всё началось', 'Я люблю тебя такой', 'Наш маленький мир', 'Незабываемые моменты', 'Впереди ещё столько глав'];
    kk_titles := array['Бәрі неден басталды', 'Мен сені осындайың үшін жақсы көремін', 'Біздің кішкентай әлеміміз', 'Ұмытылмайтын сәттер', 'Әлі талай тарау алда'];
  when 'boyfriend' then
    ru_titles := array['С чего всё началось', 'Я люблю тебя таким', 'То, что понятно только нам', 'Дни, которые мы не забудем', 'С тобой — вперёд'];
    kk_titles := array['Бәрі неден басталды', 'Мен сені осындайың үшін жақсы көремін', 'Тек екеуімізге түсінікті', 'Біз ұмытпайтын күндер', 'Сенімен бірге — алға'];
  when 'wife' then
    ru_titles := array['С чего всё началось', 'Когда «я» и «ты» стали «мы»', 'День, когда мы стали семьёй', 'Наш маленький семейный мир', 'Всё, что мы пережили вместе', 'Через всё — вместе'];
    kk_titles := array['Бәрі неден басталды', '«Мен» мен «сен» — «бізге» айналғанда', 'Отбасы болған күніміз', 'Біздің кішкентай отбасылық әлеміміз', 'Бірге бастан өткерген сәттер', 'Қандай жағдай болса да — бірге'];
  when 'husband' then
    ru_titles := array['С чего всё началось', 'Когда он стал тем самым', 'День, когда мы стали семьёй', 'Наш маленький семейный мир', 'Муж, которого вижу я', 'Через всё — вместе'];
    kk_titles := array['Бәрі неден басталды', 'Оның «дәл сол адам» екенін түсінгенде', 'Отбасы болған күніміз', 'Біздің кішкентай отбасылық әлеміміз', 'Менің көзімдегі сен', 'Қандай жағдай болса да — бірге'];
  when 'mother' then
    ru_titles := array['Там, где всё начиналось', 'Детство глазами взрослого', 'Мама, которую знаю только я', 'Не только мама', 'Мы выросли вместе', 'Всё, что я хочу тебе сказать'];
    kk_titles := array['Бәрі басталған кез', 'Балалық шаққа ересек адамның көзімен', 'Мен білетін ана', 'Тек ана ғана емес', 'Біз бірге есейдік', 'Сізге айтқым келетін сөздер'];
  when 'father' then
    ru_titles := array['Там, где всё начиналось', 'Всё, чему он меня научил', 'Папа, которого знаю только я', 'До того, как он стал папой', 'Мы менялись вместе', 'То, что я хочу успеть тебе сказать'];
    kk_titles := array['Бәрі басталған кез', 'Әкем үйреткен өмір сабақтары', 'Мен білетін әке', 'Әке атанғанға дейін', 'Біз бірге өзгердік', 'Сізге айтқым келетін сөздер'];
  when 'parents' then
    ru_titles := array['Дом, в котором всё начиналось', 'Всё, чему меня научила наша семья', 'Мама и папа, которых знаю я', 'До того, как появилась наша семья', 'Всё, что мы прошли вместе', 'То, что хочется успеть сказать'];
    kk_titles := array['Бәрі басталған үй', 'Отбасымнан үйренгенім', 'Мен білетін анам мен әкем', 'Біздің отбасы құрылғанға дейін', 'Біз бірге өткерген жол', 'Айтылып қалуы керек сөздер'];
  when 'sister' then
    ru_titles := array['Мы росли вместе', 'Ссоры, секреты и союз против всего мира', 'Сестра, которую знаю только я', 'От сестёр к близким друзьям', 'Только наши воспоминания', 'Сколько бы лет ни прошло'];
    kk_titles := array['Біз бірге өстік', 'Ұрыстар, құпиялар және екеуіңіз бір команда болған кездер', 'Мен ғана жақсы білетін жан', 'Туысқаннан жақын досқа дейін', 'Тек екеуіңізге тиесілі естеліктер', 'Қанша жыл өтсе де'];
  when 'brother' then
    ru_titles := array['Мы росли вместе', 'Шалости, соревнования и один секрет на двоих', 'Брат, которого знаю я', 'От детских ссор к настоящему доверию', 'Только наши воспоминания', 'Сколько бы лет ни прошло'];
    kk_titles := array['Біз бірге өстік', 'Тентектік, жарыс және екеуіңізге ортақ бір құпия', 'Мен білетін бауырым', 'Балалық ұрыстардан шынайы сенімге дейін', 'Тек екеуіңізге тиесілі естеліктер', 'Қанша жыл өтсе де'];
  when 'friend' then
    ru_titles := array['С чего всё началось', 'Истории, которые лучше не забывать', 'Только мы это понимаем', 'Друг, которого знаю я', 'Когда дружба становится чем-то большим', 'Ещё много историй впереди'];
    kk_titles := array['Бәрі неден басталды', 'Ұмытылмайтын оқиғалар', 'Мұны тек біз түсінеміз', 'Мен білетін досым', 'Достық жай ғана достықтан да маңызды болғанда', 'Алда әлі талай оқиға бар'];
  when 'female-friend' then
    ru_titles := array['С чего всё началось', 'Те самые истории', 'Это поймём только мы', 'Подруга, которую знаю я', 'Когда подруга становится родным человеком', 'Ещё столько всего впереди'];
    kk_titles := array['Бәрі неден басталды', 'Ұмытылмайтын оқиғалар', 'Мұны тек екеуіміз түсінеміз', 'Мен білетін құрбым', 'Құрбың туған адамыңдай жақын болғанда', 'Алда әлі талай қызық бар'];
  else
    ru_titles := array['С чего всё началось', 'Самое дорогое', 'Наши воспоминания', 'О главном и о будущем'];
    kk_titles := array['Бәрі неден басталды', 'Ең қымбат нәрселер', 'Біздің естеліктеріміз', 'Ең маңыздысы және болашақ туралы'];
  end case;
  chapter_titles := case when target_language = 'kk' then kk_titles else ru_titles end;
  system_titles := ru_titles || kk_titles || array[
    'С чего всё началось', 'Самое дорогое', 'Наши воспоминания', 'О главном и о будущем',
    'Бәрі неден басталды', 'Ең қымбат нәрселер', 'Біздің естеліктеріміз', 'Ең маңыздысы және болашақ туралы',
    'How It All Began', 'What Matters Most', 'Our Memories', 'What Matters and What Lies Ahead'
  ];
  update public.chapters as chapters
  set title = chapter_titles[chapters.position]
  where chapters.book_id = target_book_id
    and chapters.deleted_at is null
    and chapters.position between 1 and coalesce(array_length(chapter_titles, 1), 0)
    and chapters.title = any(system_titles);
  return true;
end;
$$;

revoke all on function public.set_book_language(uuid, public.book_language) from public, anon, authenticated;
grant execute on function public.set_book_language(uuid, public.book_language) to service_role;
